    function run(uint lockTime, uint amount, uint collectAmount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);
        require(lockTime <= type(uint256).max - block.timestamp);
        require(collectAmount <= amount);

        c.Put{value: amount}(lockTime);

        (uint beforeUnlockTime, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBalance = address(c).balance;

        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint afterUnlockTime, uint afterBalance) = c.Acc(address(this));
        uint afterContractBalance = address(c).balance;

        assert(reverted
            ? (afterBalance == beforeBalance && afterContractBalance == beforeContractBalance)
            : (beforeBalance >= collectAmount
                && afterBalance == beforeBalance - collectAmount
                && afterContractBalance == beforeContractBalance - collectAmount));
    }

    receive() external payable {}
}

