contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint _lockTime, uint _amount, uint _collectAmount) public payable {
        require(_amount > 0, "amount must be positive");
        require(address(this).balance >= _amount, "insufficient balance for Put");
        require(_collectAmount <= _amount, "collect amount must not exceed put amount");

        // Set up the log file and initialize so Put/Collect do not revert.
        Log log = new Log();
        c.SetLogFile(address(log));
        c.Initialized();

        // Read the caller's holder state before the Put.
        (uint unlockBefore, uint balanceBefore) = c.Acc(address(this));
        uint cBalanceBefore = address(c).balance;
        uint protocolBalanceBefore = address(this).balance;

        // Make the deciding Put call.
        c.Put{value: _amount}(_lockTime);

        // Read the resulting holder state and contract balance.
        (uint unlockAfter, uint balanceAfter) = c.Acc(address(this));
        uint cBalanceAfter = address(c).balance;

        // Attempt to Collect; this should revert because the lock time makes funds unavailable.
        bool collectReverted;
        try c.Collect(_collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // General rule: Put increases recorded balance by exactly the sent value, sets unlockTime
        // sufficiently far in the future, and traps exactly the sent Ether in the contract. Until
        // the lock expires, Collect must revert. After the lock has expired and the minimum sum
        // requirement is met, Collect of the full balance must succeed and remove the balance.
        assert(balanceAfter == balanceBefore + _amount);
        assert(unlockAfter >= unlockBefore);
        assert(cBalanceAfter == cBalanceBefore + _amount);
        assert(collectReverted == (block.timestamp <= unlockAfter));
    }

    receive() external payable {}
}

