    function run(uint lockTime, uint putAmount, uint minSum, uint collectAmount) public payable {
        require(address(this).balance >= putAmount);

        // Set up the initialization state.
        c.SetMinSum(minSum);
        c.Initialized();

        // Put Ether into c, creating a Holder with balance putAmount and unlockTime >= block.timestamp + lockTime.
        c.Put{value: putAmount}(lockTime);

