        } catch {
            collectReverted = true;
        }

        // Read the account's balance after the collect attempt.
        (uint unlockTimeAfter, uint balanceAfter) = c.Acc( address(this) );

        // A Collect must succeed exactly when the preconditions in the contract hold, and on success it must subtract exactly the collected amount.
        if (balance >= minSum && balance >= collectAmount && block.timestamp > unlockTime) {
            assert(!collectReverted && balanceAfter == balance - collectAmount);
        } else {
            assert(collectReverted && balanceAfter == balance);
        }
    }
}

